import requests
from langchain_core.tools import tool


@tool
def fetch_resource(name: str) -> str:
    """Fetch one of the explicitly configured resources."""
    destinations = {
        "status": "https://example.com/status.json",
        "help": "https://example.com/help.txt",
    }
    if name not in destinations:
        raise ValueError("Unknown resource")
    response = requests.get(destinations[name], timeout=10)
    return response.text
